test("directional PHP-Wasm callbacks carry typed recovery and expose only closure leases", () => {
	const { ir, host, closure } = structuredCallableDirectionalSubtypeIr();
	const model = compileCallablePhpGraphZendModel(ir);
	const hostModel = model.callbacks.get(host.id), closureModel = model.callbacks.get(closure.id);
	assert.equal(hostModel.direction, "host"); assert.equal(hostModel.call, undefined);
	assert.equal(hostModel.dispose, undefined); assert.equal(closureModel.direction, "closure");
	assert.equal(typeof closureModel.call, "string"); assert.equal(typeof closureModel.dispose, "string");
	const files = generateCallablePhpGraphZendAdapter(ir);
	const extension = files[`extension/${model.stem}.c`];
	assert.doesNotMatch(extension, new RegExp(`${hostModel.borrowedType}_lease_(?:call|dispose)`, "u"));
	assert.match(extension, new RegExp(closureModel.call, "u"));
	assert.match(extension, new RegExp(closureModel.dispose, "u"));
	assert.match(extension, new RegExp(`lgc_callback${hostModel.index}\\(`, "u"));
	assert.doesNotMatch(extension, new RegExp(`lgc_callback${closureModel.index}\\(`, "u"));
	assert.match(extension, /Malformed checked callback/u);
	assert.match(extension, /\.recovery = &ctx->recovery/u);
	assert.match(extension, /call->status == 10\) call->status = 1/u);
